import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';

const ZIMM_SIZE_CHIP_RECIPE = 'ZimmSizeChip';

type ZimmSizeChipProps = {
  /** Underlying size value used for selection/comparison (e.g. an SFCC variation value). */
  value: string;
  /** Visible/accessible label rendered inside the chip (e.g. "S", "M", "42"). */
  label: string;
  /** Whether this is the currently selected size. */
  isSelected: boolean;
  /**
   * Whether this size is unavailable. Sets the real native `disabled` attribute so the chip is
   * genuinely inert for both mouse and assistive tech, not just visually greyed.
   */
  isDisabled?: boolean;
  /**
   * Whether this chip is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
   * (`tabIndex={-1}`) — the caller (ZimmSizeChipGroup) drives a roving tabindex across the row.
   * Mirrors ZimmColourSwatch's identical prop, for the identical reason.
   */
  isFocusable: boolean;
  /** Selection callback, called with `value` on click. Never called when `isDisabled` is true. */
  onSelect: (value: string) => void;
};

/**
 * Atom — a single size option in a PDP size-chip row: a 28x28 button with radio semantics (one
 * selection out of the group). Purely presentational — no data-fetching hook, no keyboard
 * orchestration (that lives in the parent ZimmSizeChipGroup, matching the ZimmColourSwatch /
 * ZimmColourSwatchGroup split).
 */
export const ZimmSizeChip = ({ value, label, isSelected, isDisabled, isFocusable, onSelect }: ZimmSizeChipProps) => {
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_RECIPE, { selected: isSelected, disabled: isDisabled });

  return (
    <chakra.button
      __css={styles.chip}
      type="button"
      role="radio"
      aria-checked={isSelected}
      disabled={isDisabled}
      tabIndex={isFocusable ? 0 : -1}
      data-testid="size-chip"
      data-size-value={value}
      onClick={() => {
        // Belt-and-braces: the native `disabled` attribute above already prevents the browser
        // from ever dispatching this click, but stating the invariant explicitly means a reader
        // doesn't have to recall that fact to trust onSelect can't fire for a disabled chip.
        if (!isDisabled) onSelect(value);
      }}
    >
      {label}
    </chakra.button>
  );
};

export type { ZimmSizeChipProps };
export default ZimmSizeChip;

import type { SystemStyleObject } from '@chakra-ui/react';

/** State the atom feeds in so the recipe can resolve the Figma state cascade. */
type ZimmSizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

/**
 * Border colour precedence: disabled > selected > default — same "no state stacking" shape as
 * zimmTextInput.css.ts's resolveBorderColour. Default and Disabled both resolve to
 * 'transparent' rather than a real colour: Figma's Default/Disabled variants (nodes
 * 40003038:125875 / :125873) render as plain text with no box at all, so the always-present
 * `border` shorthand on `chip` below is made invisible rather than removed outright — the same
 * "transparent border avoids a layout shift" idiom zimmColourSwatch.css.ts's `swatch` part
 * uses for its own unselected state.
 */
export const resolveBorderColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent'; // Figma Disabled (…125873): no box, muted text only
  if (selected) return 'var(--zimm-color-border-focus)'; // Figma Selected (…125874): outline-only box
  return 'transparent'; // Figma Default (…125875): no box, plain text
};

/**
 * Background is transparent in every branch: Figma's Selected variant (…125874) is an
 * outline-only box — border present, no fill — so no state here ever paints a background.
 * Kept as an explicit disabled/selected/default cascade, matching the other two resolvers'
 * shape, rather than collapsed to a bare `'transparent'` return, so a future Figma revision
 * that does introduce a fill only has to change one branch's value.
 */
export const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent';
  if (selected) return 'transparent'; // outline-only box — was var(--zimm-color-bg-05); Figma has no fill
  return 'transparent';
};

/**
 * Text colour precedence: disabled > selected > default. Selected does NOT get an inverted
 * (white) treatment — Figma's Selected variant (…125874) keeps the same dark default text
 * colour as Default and only adds the outline box via resolveBorderColour above.
 */
export const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-text-muted)';
  if (selected) return 'var(--zimm-color-text-default)'; // no inversion — outline-only box, not filled
  return 'var(--zimm-color-text-default)';
};

/**
 * Recipe for the PDP size chip atom — a single 28x28 (--zimm-scale-700) size option, read
 * directly off the size-chip Figma component set (node 40003038:125876) for this exact
 * component's dimensions and state list. Four Figma-defined states — Default / Selected /
 * Focus / Disabled — resolved by the three `resolveXxxColour` helpers above and the
 * `_focusVisible` block below. Hover and Active/pressed are NOT part of that variant set, so
 * neither is implemented here — same "don't invent an unspecified visual state" precedent as
 * zimmColourSwatchGroup.css.ts's `pageButton` part.
 *
 * The STRUCTURE of all four states is directly confirmed against individual Figma PNG exports
 * of each variant (Default …125875, Selected …125874, Disabled …125873, Focus …130506) — not
 * inferred: Default and Disabled render as plain text with no border/box at all; Selected is
 * an outline-only box (border present, no fill — text stays the normal default colour rather
 * than inverting); Focus is Selected's border box plus an additional outer ring (confirmed by
 * its 34x34 Figma frame vs. 28x28 for the other three — the ring extends past the chip
 * itself). Only the exact border/text COLOUR TOKEN choice (`--zimm-color-border-focus` /
 * `--zimm-color-text-default` / `--zimm-color-text-muted`) remains this file's own inference
 * from precedent rather than a pixel-confirmed hex breakdown — flag for UI-designer
 * confirmation if a token choice doesn't match.
 */
export const ZimmSizeChip = {
  parts: ['chip'],
  baseStyle: (props: ZimmSizeChipStyleProps): Record<string, SystemStyleObject> => ({
    chip: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-700)', // 28px
      height: 'var(--zimm-scale-700)', // 28px
      // Width/style stay constant across every state; only borderColor toggles between
      // 'transparent' (Default/Disabled — no visible box) and a real token (Selected) — see
      // resolveBorderColour above.
      border: 'var(--zimm-border-width-default) solid',
      borderColor: resolveBorderColour(props),
      background: resolveBackgroundColour(props),
      color: resolveTextColour(props),
      textStyle: 'buttonSm',
      padding: 0,
      outline: 'none',
      cursor: props.disabled ? 'not-allowed' : 'pointer',
      _focusVisible: {
        // Figma's Focus variant (…130506) shows a border box even when the chip isn't
        // selected, so focus-visible applies the same border colour Selected uses, on top of
        // (not instead of) the outer ring — an unselected-but-tabbed-to chip still gets a
        // visible box, not just a ring around otherwise-invisible bounds.
        borderColor: 'var(--zimm-color-border-focus)',
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

import type { SystemStyleObject } from '@chakra-ui/react';
// Shared with zimmProductCard.css.ts's own identical need (its PLP bag-icon mobile hide) —
// extracted to zimmProductCardShared.ts for the same reason HOVER_CAPABLE_QUERY already is there:
// a module-private copy in each file is exactly the same-value-typed-twice drift risk a shared
// constant removes. See that module's own comment for why the underlying breakpoints token has
// to be imported directly rather than referenced as var(--zimm-*) — media queries can't consume
// CSS custom properties.
import { DESKTOP_QUERY } from '../../zimmProductCardShared';

/** State the atom feeds in so the recipe can resolve the bag button's disabled treatment —
 *  named `disabled`, not `isUnavailable`, to match `recipeGuards.test.ts`'s own
 *  `DEFAULT_STYLE_PROPS` key so that guard's exhaustive prop-combination walk actually exercises
 *  both branches. Same reasoning `zimmSizeChip.css.ts` documents for its own `disabled` prop. */
type ZimmProductCardContentStyleProps = {
  disabled?: boolean;
};

// Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
// zimmNavItem, zimmColourSwatchGroup's pageButton, zimmProductCardMedia's close/arrowButton/
// scrollContainer) — no Figma spec exists for focus on any of this component's three
// interactive parts (nameLink, bagButton, notifyMeButton), same situation those precedents were
// already in. This gap was caught twice already in this build (Step 2, Step 4); not repeating it.
const FOCUS_VISIBLE: SystemStyleObject = {
  outline: 'var(--zimm-focus-ring)',
  outlineOffset: 'var(--zimm-focus-ring-offset-default)',
};

/**
 * Recipe for the product-card text-content block (ui-kits/molecules/zimmProductCardContent).
 * Figma "Card-content" component set, node 40002109:26908 (Desktop 40002109:26906).
 *
 * Vertical rhythm is expressed as `marginTop` on each row rather than a uniform `root.gap`,
 * because the confirmed Figma offsets are NOT uniform:
 *   - 16px between the name row (height 25) and the attributes row (starts at y=41): 41-25=16.
 *   - 24px between the name+attributes block (height 49) and the price (starts at y=73): 73-49=24.
 *   - 24px between the price frame (height 82) and the (hidden by default) size-selector slot
 *     (starts at y=106): 106-82=24.
 * These margins apply regardless of which sibling actually precedes a given row (e.g. price's
 * marginTop is the same whether or not the attributes row rendered above it) — no distinct value
 * is confirmed for that specific combination, so the same rhythm is reused rather than invented.
 *
 * `root`'s outer padding IS genuinely responsive — a real, confirmed gap, not a missing
 * responsive split on an otherwise-correct single value. An earlier revision of this docblock
 * asserted nothing correctness-critical differed by breakpoint and shipped `root` with no
 * padding at all, on any breakpoint; that claim was never actually checked against the Mobile
 * variant and is corrected now that it has been. Confirmed via get_design_context on the two
 * real assembled card instances (not just the standalone documentation set):
 *   - Desktop (node 40002163:41443, the real assembled Desktop/Default/PLP-PDP card's
 *     Card-content): padding-top 32px, padding-inline 40px.
 *   - Mobile (node 40002163:37103, the Mobile Card-content variant): padding-top 16px,
 *     padding-inline 32px.
 * These are genuinely different values, not the same padding read at a smaller viewport, so
 * `root` carries an explicit `DESKTOP_QUERY` step (mobile-first: the
 * base values are the Mobile ones, overridden at the desktop breakpoint) rather than a single
 * baseStyle value — see .claude/rules/overrideStyling.md's "explicit media queries, not
 * Chakra's array shorthand" rule.
 *
 * Parts:
 *   - `root` — the outermost flex column; carries the responsive outer padding above.
 *   - `nameRow` — Figma's "Product name and icons": the heading link + bag icon, space-between.
 *   - `nameLink` — the router `<Link>` wrapping the composed ZimmProductName heading.
 *   - `bagWrapper` / `bagButton` — Figma's "Icons" group and its 24x24 `touchContainer` button.
 *   - `attributesRow` / `colourText` / `sizeText` — the wishlist-only colour/size meta line.
 *   - `priceWrapper` — wraps the composed ZimmProductPrice (always rendered).
 *   - `sizeChipWrapper` — wraps the composed ZimmSizeChipGroup (PLP-only when rendered at all).
 *   - `notifyMeButton` — the out-of-stock notify-me CTA, the shared CTA/Link atom instance
 *     (Figma node 40002163:41468; full citation in index.tsx).
 */
export const ZimmProductCardContent = {
  parts: [
    'root',
    'nameRow',
    'nameLink',
    'bagWrapper',
    'bagButton',
    'attributesRow',
    'colourText',
    'sizeText',
    'priceWrapper',
    'sizeChipWrapper',
    'notifyMeButton',
  ],

  baseStyle: ({ disabled }: ZimmProductCardContentStyleProps): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      // Mobile-first base values — Figma node 40002163:37103 (Mobile Card-content variant).
      // See the module docblock above for the full citation and why this genuinely differs by
      // breakpoint rather than collapsing to one value.
      paddingTop: 'var(--zimm-scale-m)', // 16px
      paddingInline: 'var(--zimm-scale-2xl)', // 32px
      [DESKTOP_QUERY]: {
        // Desktop override — Figma node 40002163:41443 (Desktop/Default/PLP-PDP Card-content).
        paddingTop: 'var(--zimm-scale-2xl)', // 32px
        paddingInline: 'var(--zimm-scale-3xl)', // 40px
      },
    },

    nameRow: {
      display: 'flex',
      // 'flex-start', not 'center': `nameRow`'s height is driven by however many lines the
      // product name wraps to, which grows unbounded with a long name. `center` re-centres the
      // bag icon against the WHOLE grown block, so it visibly drifts downward as the name gets
      // longer — the defect this replaces. `flex-start` anchors both children to the row's top
      // edge regardless of how many lines the name occupies, pinning the icon to the *first*
      // line specifically, with no compensating margin needed on `bagWrapper` below: measured
      // directly (not estimated from Figma auto-layout padding, which does not correspond 1:1 to
      // a real CSS line-height), the name's actual rendered single-line height is 18px —
      // *shorter* than the icon's own 24px, the opposite of what an earlier revision of this
      // comment assumed. The icon is the taller of the two, so at `flex-start` it already sits
      // flush with the row's top with zero offset needed — exactly where it already sat in the
      // previous `center`-aligned single-line case (centering an 18px name against a
      // 24px-icon-determined row leaves the icon at 0 offset there too; only the shorter name
      // was ever inset by the few spare pixels). A `marginTop` on `bagWrapper` was tried and
      // was wrong: it made `bagWrapper`'s own margin+content footprint (4+24=28px) taller than
      // even the single-line name (18px), so it — not the name — became nameRow's own height
      // driver, and the icon ended up sitting visibly lower than the first line instead of flush
      // with it.
      alignItems: 'flex-start',
      justifyContent: 'space-between',
      // 8px — Figma: the 24px icon column starts at x=184 inside the 208px row, and the name
      // column is 176px wide (208 - 176 - 24 = 8).
      gap: 'var(--zimm-scale-xs)',
    },

    nameLink: {
      display: 'block',
      flex: '1 1 auto',
      minWidth: 0,
      color: 'inherit',
      textDecoration: 'none',
      _focusVisible: FOCUS_VISIBLE,
    },

    bagWrapper: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
    },

    bagButton: {
      display: 'flex',
      // 'flex-start', not 'center': the 24px touch target (below) exists for WCAG 2.5.8's
      // minimum tap-area requirement, not because the visible glyph itself is 24px — `ZimmIcon`
      // defaults to `size="md"` (16px, `foundation/sizes.ts`'s `iconSizes.md`), so centering it
      // inside a 24px box leaves 4px of slack above and below and visibly offsets the glyph 4px
      // below the button's own top edge. That 4px was invisible to every fix so far in this
      // file, because `nameRow`/`bagWrapper` alignment only ever controlled the *button's own
      // box* position (already confirmed flush with the row's top) — never the icon's position
      // *within* that box. `flex-start` here pins the visible glyph itself to the top of its
      // touch target, matching the button's own top edge exactly.
      alignItems: 'flex-start',
      justifyContent: 'center',
      width: 'var(--zimm-scale-600)', // 24px — Figma touchContainer, meets WCAG 2.5.8
      height: 'var(--zimm-scale-600)',
      background: 'transparent',
      border: 'none',
      padding: 0,
      color: disabled ? 'var(--zimm-color-text-muted)' : 'var(--zimm-color-text-default)',
      cursor: disabled ? 'not-allowed' : 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },

    attributesRow: {
      display: 'flex',
      alignItems: 'center',
      // 2px — confirmed via get_design_context on node 40002187:58446 (the real Wishlist
      // Card-content instance): the Attributes container's two text children have an explicit
      // `gap-[2px]` between them. Supersedes an earlier placeholder (`--zimm-scale-2xs`, 4px)
      // that was reused from zimmProductStyleCode.css.ts's label/value gap on the assumption
      // that "no horizontal offset is given" in Figma for this pair — a real value exists now.
      gap: 'var(--zimm-scale-3xs)',
      marginTop: 'var(--zimm-scale-m)', // 16px — see docblock above
    },

    colourText: {
      margin: 0,
      // Matches zimmProductStyleCode.css.ts's meta-text treatment: caption size + secondary
      // colour, deliberately quieter than the product name above it.
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    sizeText: {
      margin: 0,
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    priceWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
      // Defensive: this is a direct flex item of root's column flex with no width property of
      // its own, so it defaults to `min-width: auto` — refusing to shrink below its content's
      // min-content size. Belt-and-braces alongside zimmProductPrice.css.ts's own flexWrap fix
      // (the actual root cause of the was/now mobile overflow), not a substitute for it.
      minWidth: 0,
    },

    // Deliberately no `display` value at all here — Figma's `hidden=true` default on this slot
    // is the Step 6 organism's hover-reveal CSS to implement on top of this component's always-
    // rendered output, not something this component's own recipe enforces (see index.tsx's
    // data-card-slot contract comment). Setting `display: 'none'` here would fight whatever the
    // organism's hover-reveal CSS tries to do.
    sizeChipWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
    },

    notifyMeButton: {
      // 24px — matches priceWrapper/sizeChipWrapper's own marginTop above: Figma's "Content"
      // wrapper (the flex column holding name-block, price, and this notify-me link) applies a
      // uniform 24px gap between ALL direct children, confirmed via get_design_context on node
      // 40002163:41470 (Desktop, Hover, PLP/PDP, Unavailable=True). Supersedes an earlier
      // placeholder value shipped before this was confirmed.
      marginTop: 'var(--zimm-scale-xl)',
      display: 'block',
      background: 'transparent',
      border: 'none',
      padding: 0,
      textAlign: 'left',
      textStyle: 'linkSm',
      // alias/color/link/default (Figma) — not text/default, even though both resolve to the
      // same hex in this palette. Confirmed via get_design_context on node 40002163:41468, the
      // "CTA/Link" atom instance (40001908:28374/40001908:28368) this control reuses.
      color: 'var(--zimm-color-link-default)',
      cursor: 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },
  }),
};

