import { describe, test, expect } from 'vitest';
import { ZimmSizeChipGroup } from './zimmSizeChipGroup.css';

/**
 * `index.test.tsx` mocks `useMultiStyleConfig` globally, so this recipe's own object shape is
 * never exercised by any shipped component test — these assertions are the only thing that
 * actually reads it. Guards against two regressions found across two separate audits:
 * `radiogroup` originally shipped with no `justifyContent`/`gap` at all (SFCC-236 Step 6, chips
 * touching), then was fixed to `justifyContent: 'space-between'` — which matched a real page
 * instance (40002163:41459) only because that instance happens to hold exactly 6 chips filling
 * its 208px width (6×28px + 5×8px gaps = 208px). A 2026-09-10 audit checked the real master
 * component (40003066:34867) instead and found a fixed 8px gap, independent of chip count/row
 * width — `space-between` silently diverges from that the moment a product has fewer than 6
 * sizes (wider gaps instead of a narrower row).
 */
describe('ZimmSizeChipGroup — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmSizeChipGroup.baseStyle());
    expect(parts.sort()).toEqual([...ZimmSizeChipGroup.parts].sort());
  });

  test('radiogroup uses a fixed 8px gap, not justifyContent — matches the real Figma master component (40003066:34867: 6 chips at x=0/36/72/108/144/180, each 28px wide, an 8px gap regardless of row width)', () => {
    const { radiogroup } = ZimmSizeChipGroup.baseStyle();
    expect((radiogroup as Record<string, unknown>).gap).toBe('var(--zimm-scale-200)');
    expect(Object.prototype.hasOwnProperty.call(radiogroup, 'justifyContent')).toBe(false);
  });

  test('oneSize renders as a bordered box with the caption textStyle, not buttonSm — matches the real Figma "Type=One Size" node (40003066:34866), a static label rather than a button', () => {
    const { oneSize } = ZimmSizeChipGroup.baseStyle();
    expect((oneSize as Record<string, unknown>).border).toBe(
      'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
    );
    expect((oneSize as Record<string, unknown>).textStyle).toBe('caption');
  });
});

