388	 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
389	 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
390	 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
391	 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
392	 * (making the desktop arrows permanently visible regardless of pointer capability) left the
393	 * whole suite green. These tests import the recipe module directly and call its exported
394	 * baseStyle(), bypassing the mock entirely — same technique as
395	 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
396	 */
397	describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
398	  /**
399	   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
400	   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
401	   * instance checked, visible only on the matching Hover-state instance, for both PLP and
402	   * Wishlist). This test used to assert `carousel[HOVER_CAPABLE_QUERY].display === 'flex'` —
403	   * i.e. that ANY hover-capable device (not just an actually-hovering one) revealed the arrows
404	   * at THIS recipe's own level. That was the bug: a device-CAPABILITY check standing in for an
405	   * actual-hover check made the arrows permanently visible on desktop. The
406	   * `[HOVER_CAPABLE_QUERY]: { display: 'flex' }` sub-block that produced that value has been
407	   * removed from `carousel` entirely — the real hover/has(:focus-visible) reveal now lives one layer up,
408	   * on `ZimmProductCard`'s own organism recipe (`zimmProductCard.css.ts` docblock point 6),
409	   * scoped to the whole card via `&:hover`/`&:has(:focus-visible)`, which this Media-only recipe has no
410	   * visibility into (there is no composing organism root here to hover). See that file's own
411	   * "real recipe assertions" describe block for the reveal-rule regression guard.
412	   */
413	  test('carousel (arrows) has no reveal of its own at this recipe level — stays display:none unconditionally; indicatorWrapper is unaffected by the fix', () => {
414	    const style = ZimmProductCardMediaRecipe.baseStyle();
415	
416	    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows
417	    // display:none. Fix J (SFCC-236) converted this part's unconditional hidden state from
418	    // `display: 'none'` to `clipPath: 'inset(50%)'` so the arrows would stay in the DOM/tab
419	    // order/accessibility tree even while clipped — Fix K (CodeRabbit finding on PR #85) reverted
420	    // that specifically here: this rule applies on EVERY pointer type, including touch, which
421	    // never enters the hover-capable reveal path at all (no `[HOVER_CAPABLE_QUERY]` key exists on
422	    // this part — see below), so clip-path left each arrow `<button>` permanently tabbable with no
423	    // way for a touch pointer to ever reveal it. Back to `display: 'none'` here; the hover-capable
424	    // override (where a reveal genuinely is possible) now lives on `zimmProductCard.css.ts`'s own
425	    // `[HOVER_CAPABLE_QUERY]` block instead (see that file's own Fix K note and "real recipe
426	    // assertions" describe block).
427	    expect(style.indicatorWrapper.display).toBe('block');
428	    expect(style.carousel.display).toBe('none');
429	    expect((style.carousel as Record<string, unknown>).clipPath).toBeUndefined();
430	
431	    // Hover-capable pointers: indicatorWrapper still hides itself via its own
432	    // `[HOVER_CAPABLE_QUERY]` key (unchanged by this fix) — but `carousel` still has no
433	    // `[HOVER_CAPABLE_QUERY]` key AT ALL at this recipe level (the hover-capable override now
434	    // lives on the organism instead). Regression guard: if a `[HOVER_CAPABLE_QUERY]` key ever
435	    // reappears here with an unconditional `display: 'flex'`, the permanent-visibility bug
436	    // (Fix J's own original motivation) is back.
437	    const carousel = style.carousel as Record<string, unknown>;
438	    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
439	    expect(carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();
440	    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
441	    expect(indicatorHoverBlock.display).toBe('none');
442	  });
