488	        <ZimmProductCardMedia primaryImage={PRIMARY} images={SHRUNK_GALLERY} swapOnHover={false} showControls />
489	      </IntlProvider>,
490	    );
491	
492	    // ZimmSlideIndicator's own display-side clamp masks the stale state right here too — it also
493	    // reads "2 of 2", which is exactly what makes the underlying bug invisible without also
494	    // exercising the very next click below.
495	    expect(screen.getByRole('group', { name: 'Image 2 of 2' })).toBeInTheDocument();
496	
497	    const nextAfterShrink = screen.getByRole('button', { name: 'Next image' });
498	    await user.click(nextAfterShrink); // must wrap 2nd -> 1st on THIS click, not require a second one
499	
500	    expect(screen.getByRole('group', { name: 'Image 1 of 2' })).toBeInTheDocument();
501	  });
502	});
503	
504	describe('ZimmProductCardMedia — scrollend listener drives the touch indicator (Fix 4 regression)', () => {
505	  test('a real scrollend event with a simulated scroll position updates the indicator', () => {
506	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
507	    const container = screen.getByTestId('card-media-scroll');
508	
509	    // jsdom performs no real layout, so clientWidth/scrollWidth/scrollLeft all default to 0 —
510	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
511	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
512	    const SIMULATED_SLIDE_WIDTH = 300;
513	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
514	    Object.defineProperty(container, 'scrollWidth', {
515	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
516	      configurable: true,
517	    });
518	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * 1, configurable: true });
519	
520	    // A raw `container.dispatchEvent(...)` bypasses @testing-library/react's configured
521	    // `eventWrapper`, so the resulting setCurrentIndex call is never flushed before the
522	    // assertion below runs. Routing the same native Event through RTL's generic `fireEvent`
523	    // call form (not one of its `fireEvent.<type>` convenience methods — `scrollend` isn't one
524	    // of those) dispatches the identical event while going through that act()-wrapping config.
525	    fireEvent(container, new Event('scrollend'));
526	
527	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
528	  });
529	});
530	
531	/**
532	 * The `scrollend`-only tracking above lags for the whole duration of an active drag (it only
533	 * fires once the gesture settles) — confirmed live once a related fix made the swipe gesture
534	 * itself reachable for the first time. These tests cover the `scroll`-driven live-tracking path
535	 * added alongside it: see index.tsx's own updated comment above the effect for the full
536	 * reasoning. jsdom (this suite's Vitest environment) implements a real, timer-backed
537	 * `requestAnimationFrame`, so the throttled update is genuinely asynchronous here, not merely
538	 * simulated — the same real-rAF-plus-`waitFor` precedent already used by
539	 * list-menu-popover.test.tsx's own double-rAF-deferred assertions.
540	 */
541	describe('ZimmProductCardMedia — scroll listener drives the touch indicator live during an active drag', () => {
542	  const SIMULATED_SLIDE_WIDTH = 300;
543	
544	  /** Same "jsdom performs no real layout, but these are plain definable properties" approach as
545	   *  the `scrollend` test above — sets a plausible clientWidth/scrollWidth/scrollLeft for a
546	   *  given slide index directly. */
547	  const simulateScrollPosition = (container: HTMLElement, slideIndex: number) => {
548	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
549	    Object.defineProperty(container, 'scrollWidth', {
550	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
551	      configurable: true,
552	    });
553	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * slideIndex, configurable: true });
554	  };
555	
556	  test('a real scroll event with a simulated scroll position updates the indicator once the throttled animation frame runs', async () => {
557	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
558	    const container = screen.getByTestId('card-media-scroll');
559	    simulateScrollPosition(container, 1); // 2nd of 3 slides
560	
561	    // fireEvent (not a raw dispatchEvent) routes through RTL's act()-wrapping config, same
562	    // reasoning as the scrollend test above — necessary here too even though the resulting
563	    // setCurrentIndex call is additionally deferred behind a real requestAnimationFrame.
564	    fireEvent(container, new Event('scroll'));
565	
566	    // Unlike the scrollend path, this update is intentionally NOT synchronous — it is coalesced
567	    // behind a real requestAnimationFrame callback, so the assertion has to wait it out rather
568	    // than read the DOM immediately.
569	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument());
570	  });
571	
572	  test('several scroll events fired before the pending animation frame runs are coalesced into a single requestAnimationFrame call, not one per event', async () => {
573	    // spyOn (no mockImplementation) still calls through to jsdom's real rAF — this only adds a
574	    // call-count tripwire on top of the real, unthrottled behavior it would otherwise have.
575	    const rafSpy = vi.spyOn(window, 'requestAnimationFrame');
576	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
577	    const container = screen.getByTestId('card-media-scroll');
578	    simulateScrollPosition(container, 1);
579	
580	    // Simulates the many `scroll` events a real touch-driven drag fires per second, all
581	    // dispatched before the browser has had any chance to run the first queued animation frame.
582	    fireEvent(container, new Event('scroll'));
583	    fireEvent(container, new Event('scroll'));
584	    fireEvent(container, new Event('scroll'));
585	
586	    // The `rafId !== null` guard means only the FIRST of the three calls above actually schedules
587	    // a frame — this is the throttling behavior itself, not merely "it eventually updates".
588	    expect(rafSpy).toHaveBeenCalledTimes(1);
589	
590	    // The position by the time the coalesced frame actually runs — proves the update reflects
591	    // the latest scroll position at that point, not whatever was current at the first event.
592	    simulateScrollPosition(container, 2);
593	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument());
594	
595	    // Once that frame has run (clearing rafId back to null), a later scroll event schedules a
596	    // new one — the throttle resets every frame rather than firing only ever once.
597	    fireEvent(container, new Event('scroll'));
598	    expect(rafSpy).toHaveBeenCalledTimes(2);
599	
600	    rafSpy.mockRestore();
601	  });
602	});
603	
604	describe('ZimmProductCardMedia — scroll container is keyboard-operable regardless of pointer capability (Fix 5)', () => {
605	  test('ArrowRight/ArrowLeft on the scroll container wrap at both ends, the same as the visible arrows, even with showControls false', () => {
606	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls={false} />);
607	    const container = screen.getByTestId('card-media-scroll');
608	
609	    expect(container).toHaveAttribute('tabindex', '0');
610	
611	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 0 -> 1
612	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 1 -> 2 (last)
613	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
614	
615	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // wraps 2 -> 0
616	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
617	
618	    fireEvent.keyDown(container, { key: 'ArrowLeft' }); // wraps 0 -> 2 (last)
619	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
620	  });
621	
622	  test('the scroll container is not keyboard-focusable when there is only one image', () => {
623	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
624	    const container = screen.getByTestId('card-media-scroll');
625	    expect(container).not.toHaveAttribute('tabindex');
626	  });
627	});
